Definition D_main_cells : list (Z * nat) :=
  [(0x49770%Z, 8%nat); (0x69ad0%Z, 8%nat); (0x69b30%Z, 8%nat); (0x69af8%Z, 8%nat); (0x69ac0%Z, 8%nat); (0x69ab8%Z, 8%nat); (0x69868%Z, 8%nat); (0x69878%Z, 8%nat); (0x69870%Z, 8%nat); (0x69ae0%Z, 8%nat); (0x69ae8%Z, 8%nat); (0x49850%Z, 8%nat); (0x49838%Z, 8%nat); (0x49778%Z, 8%nat); (0x69ac8%Z, 1%nat); (0x497a0%Z, 4%nat); (0x49798%Z, 4%nat); (0x49810%Z, 8%nat); (0x497f0%Z, 8%nat); (0x49780%Z, 8%nat); (0x49788%Z, 8%nat); (0x49790%Z, 8%nat); (0x69aa8%Z, 4%nat); (0x69aac%Z, 4%nat); (0x69aa9%Z, 1%nat); (0x49830%Z, 8%nat); (0x396f0%Z, 1%nat)].

Definition range_disjoint_b (a : Z) (n : nat) (c : Z * nat) : bool :=
  ((a + Z.of_nat n <=? fst c) || (fst c + Z.of_nat (snd c) <=? a))%Z.

Definition D_main_missb (a : Z) (n : nat) : bool :=
  forallb (range_disjoint_b a n) D_main_cells && (0 <=? a)%Z && (a + Z.of_nat n <=? 0x6b000)%Z.

(* [comment removed for export] *)
Definition djw (P : Prop) : Prop := P.

Section VP1. Context {fx : FPState}.   (* [comment removed for export] *)
Lemma range_disjoint_djw : forall a n c,
  range_disjoint_b a n c = true ->
  djw (a + Z.of_nat n <= fst c \/ fst c + Z.of_nat (snd c) <= a)%Z.
Proof.
